CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 REAL CHECK(c0 IS NULL OR length(c0) < 40), c1 REAL, c2 ANY NOT NULL DEFAULT 0, c3 REAL, c4 INTEGER) STRICT;
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(-8.148, -28.077, 'tau', -26.884, 183);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(-20.675, -12.124, '日本', -42.655, 126);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 ANY COLLATE NOCASE, c1 INTEGER, c2 ANY NOT NULL DEFAULT 0, c3 TEXT COLLATE NOCASE) STRICT;
INSERT OR IGNORE INTO t1(c0, c1, c2, c3) VALUES(0, -490, 'it''s', 'Ελλάδα');
INSERT OR IGNORE INTO t1(c0, c1, c2, c3) VALUES(0, 443, 1, 'tau');
SELECT length('señor'), upper('señor'), lower('señor'), substr('señor', 0, 4), instr('señor', 'it''s'), replace('señor', 'e', 'XY'), trim('señor'), ltrim('señor', 'ab'), hex('señor'), quote('señor'), unicode('señor'), 'señor' LIKE '%', 'señor' GLOB '*[a-m]*', char(66, 248), 'señor' || 'it''s', 'señor' < 'it''s', 'señor' = 'it''s' COLLATE NOCASE;
SELECT length('a%b'), upper('a%b'), lower('a%b'), substr('a%b', -3, 5), instr('a%b', 'psi'), replace('a%b', 'a', 'XY'), trim('a%b'), ltrim('a%b', 'ab'), hex('a%b'), quote('a%b'), unicode('a%b'), 'a%b' LIKE '%a_', 'a%b' GLOB '?', char(65, 797), 'a%b' || 'psi', 'a%b' < 'psi', 'a%b' = 'psi' COLLATE NOCASE;
SELECT length('zeta'), upper('zeta'), lower('zeta'), substr('zeta', 1, 5), instr('zeta', 'omicron'), replace('zeta', '', '_'), trim('zeta'), ltrim('zeta', 'ab'), hex('zeta'), quote('zeta'), unicode('zeta'), 'zeta' LIKE '%a_', 'zeta' GLOB 'a*', char(68, 683), 'zeta' || 'omicron', 'zeta' < 'omicron', 'zeta' = 'omicron' COLLATE NOCASE;
SELECT length('MU'), upper('MU'), lower('MU'), substr('MU', -1, 5), instr('MU', 'kappa'), replace('MU', '', ''), trim('MU'), ltrim('MU', 'ab'), hex('MU'), quote('MU'), unicode('MU'), 'MU' LIKE '%', 'MU' GLOB '?', char(71, 566), 'MU' || 'kappa', 'MU' < 'kappa', 'MU' = 'kappa' COLLATE NOCASE;
SELECT length('nu'), upper('nu'), lower('nu'), substr('nu', 3, 3), instr('nu', 'phi'), replace('nu', 'e', '_'), trim('nu'), ltrim('nu', 'ab'), hex('nu'), quote('nu'), unicode('nu'), 'nu' LIKE '%', 'nu' GLOB '?', char(73, 629), 'nu' || 'phi', 'nu' < 'phi', 'nu' = 'phi' COLLATE NOCASE;
SELECT printf('%g', -158), round(-158, 1), -158 * 659.5, -158 / 3, CAST(-158 AS TEXT), -158 + 0.0;
SELECT id, c4, ntile(3) OVER (ORDER BY id) FROM t0 ORDER BY id;
SELECT a.id, b.id, a.c0, b.c1 FROM t1 a CROSS JOIN t1 b ORDER BY 1, 2 LIMIT 36;
SELECT count(*) FROM t1 a JOIN t1 b USING(id) WHERE a.coalesce(coalesce(c0, NULL), abs(c0));
